mapper.update:
update t_msg_template
set tpl_title = #{title}, tpl_content = #{content}, tpl_channel = #{channel}, tpl_status = #{status}
where tpl_id = #{id} and tpl_company_id = #{companyId}

update t_cmp_dept
set dept_name = #{deptName}, leader = #{leader}, order_num = #{orderNum}, status = #{status}
where dept_id = #{id} and company_id = #{companyId}

update t_cmp_integration
set status = #{status}, config_json = #{configJson}
where company_id = #{companyId} and provider_code = #{provider}

update sys_user u
set u.status = #{status}
where u.user_id = #{userId}
  and exists (select 1 from t_cmp_binding b where b.bnd_user_id = #{userId} and b.bnd_company_id = #{companyId})
